param([Parameter(Mandatory=$true)][string]$MainPath,[Parameter(Mandatory=$true)][string]$ServicePath,[Parameter(Mandatory=$true)][string]$HeaderPath)
$ErrorActionPreference='Stop'
function A([bool]$x,[string]$m){if(!$x){throw $m}}
function O([string]$t,[string[]]$v,[string]$n){$p=-1;foreach($x in $v){$q=$t.IndexOf($x,$p+1);A ($q-gt$p) "$n $x";$p=$q}}
function V([string]$m,[string]$s,[string]$h){
 foreach($x in @('LOADER_PERSISTENT_STATUS_BUSY','LOADER_PERSISTENT_STATUS_TIMEOUT','canonical detached V3 status proof','A missing device never permits cleanup')){A ($h.Contains($x)) "header $x"}
 $v=$s.Substring($s.IndexOf('LoaderValidateDetachedStatus'),$s.IndexOf('LoaderDecideScmCleanup')-$s.IndexOf('LoaderValidateDetachedStatus'))
 foreach($x in @('status_size != sizeof(status)','Version !=','HeaderSize !=','RecordSize !=','TotalSize !=','ContextCount != 0u','LifecycleState != LOADER_PERSISTENT_STATUS_UNLOADED','Flags != 0u','Reserved != 0u','FirstOperationStatus != 0','FirstOperationIndex != VMX_PERSISTENT_PUBLIC_STATUS_NO_INDEX','FirstCleanupStatus != 0','FirstCleanupIndex != VMX_PERSISTENT_PUBLIC_STATUS_NO_INDEX')){A ($v.Contains($x)) "validator $x"}
 $p=$s.Substring($s.IndexOf('LoaderDecideScmCleanup'),$s.IndexOf('LoaderEvaluateServiceAbsence')-$s.IndexOf('LoaderDecideScmCleanup'));A ($p.Contains('!device_opened || status_proof != LOADER_PERSISTENT_STATUS_DETACHED')) 'proof gate'
 $q=$m.Substring($m.IndexOf('#define LOADER_PERSISTENT_STATUS_MAX_CONTEXTS'),$m.IndexOf('static LOADER_PERSISTENT_STATUS_PROOF QueryPersistentDetachedStatus')-$m.IndexOf('#define LOADER_PERSISTENT_STATUS_MAX_CONTEXTS'))
 A ($q-notmatch 'QueryBytes|QueryError|QuerySucceeded') 'no failed-call size discovery'
 $t=$q.Substring($q.IndexOf('PersistentStatusQueryThread'),$q.IndexOf('static BOOL QueryPersistentStatus')-$q.IndexOf('PersistentStatusQueryThread'));O $t @('FetchSucceeded = DeviceIoControl','context->Status, context->StatusSize','&context->FetchBytes','FetchError =') 'thread order';A (([regex]::Matches($t,'DeviceIoControl')).Count-eq1) 'one bounded query'
 O $q @('LOADER_PERSISTENT_STATUS_MAX_CONTEXTS 4096u','StatusSize = LOADER_PERSISTENT_STATUS_MAX_BYTES','HeapAlloc','DuplicateHandle','CreateThread','WaitForSingleObject(thread, timeout_ms)','CancelSynchronousIo(thread)','WaitForSingleObject(thread, 5000u)','LOADER_PERSISTENT_STATUS_TIMEOUT','FetchError == ERROR_BUSY','!context->FetchSucceeded','ERROR_INSUFFICIENT_BUFFER','ERROR_MORE_DATA','FetchBytes > context->StatusSize','FetchBytes < VMX_PERSISTENT_PUBLIC_STATUS_HEADER_SIZE','LoaderClassifyPersistentStatus','FreePersistentStatusQueryContext') 'query'
 $u=$m.Substring($m.IndexOf('static int CmdUnload'),$m.IndexOf('static int CmdHook')-$m.IndexOf('static int CmdUnload'))
 $n=$u.Substring($u.IndexOf('if (!OpenDevice())'),$u.IndexOf('/* Send IOCTL_UNLOAD')-$u.IndexOf('if (!OpenDevice())'));O $n @('leaving the service installed for retry','CloseServiceHandle(g_scm_handle)','return 1') 'no device';A ($n-notmatch 'OpenService|StopDriver|DeleteDriver|QueryPersistent') 'no device side effects'
 O $u @('OpenDevice()','IOCTL_HYPERVISOR_UNLOAD','LOADER_UNLOAD_IOCTL_SUCCESS','LOADER_UNLOAD_IOCTL_NOT_LOADED','QueryPersistentDetachedStatus()','LoaderDecideScmCleanup(TRUE, ioctl_result, status_proof)','LOADER_SCM_CLEANUP_FORBIDDEN','return 1','CleanupDriverServiceAfterDetachedProof()') 'unload'
}
$m=[IO.File]::ReadAllText((Resolve-Path $MainPath));$s=[IO.File]::ReadAllText((Resolve-Path $ServicePath));$h=[IO.File]::ReadAllText((Resolve-Path $HeaderPath));V $m $s $h
foreach($x in @($s.Replace('!device_opened || status_proof != LOADER_PERSISTENT_STATUS_DETACHED','false'),$s.Replace('status.ContextCount != 0u','false'),$m.Replace('status_proof = QueryPersistentDetachedStatus();','status_proof = LOADER_PERSISTENT_STATUS_DETACHED;'),$m.Replace('CancelSynchronousIo(thread)','CloseHandle(thread)'),$m.Replace('StatusSize = LOADER_PERSISTENT_STATUS_MAX_BYTES','StatusSize = VMX_PERSISTENT_PUBLIC_STATUS_HEADER_SIZE'),$m.Replace('FetchBytes > context->StatusSize','FALSE'),$m.Replace('if (!OpenDevice())','if (false)'),$m.Replace('scm_cleanup_ok = CleanupDriverServiceAfterDetachedProof();','scm_cleanup_ok = TRUE;'))){$bad=$false;try{V $m $x $h}catch{$bad=$true};if($x.Contains('CmdUnload')-or$x.Contains('PersistentStatusQueryThread')){$bad=$false;try{V $x $s $h}catch{$bad=$true}};A $bad 'accepted mutation'}
'Verified loader cleanup: bounded one-shot 0x807 retrieval, canonical tombstone, fail-closed proof, and confirmed service absence.'
